function fixed(abbr, zone, offset, place, extra = "") {
    return {
        zone,
        note: `${abbr} is a fixed offset (${offset}), read as ${zone}: it never follows daylight saving. ` +
            `For the place and its clock changes, pass "${place}" instead.${extra ? ` ${extra}` : ""}`,
    };
}
